        if (input > 0 && input <= filesToHash.size())
        {
            selectedFiles.push_back(filesToHash[input - 1]);
            numSelected++;
        }
        else if (input == 0)
        {
            break; // Terminar o loop de seleção
        }
        else
        {
            std::cout << "Número inválido. Por favor, tente novamente." << std::endl;
